use std::collections::{BTreeMap, BTreeSet};
use crate::model::{Objective, Plan, ScanPlan, Shell, Study};

fn allowed(c:char,h:i32,k:i32,l:i32)->bool{match c{'P'=>true,'I'=>(h+k+l)%2==0,'F'=>(h%2==k%2)&&(k%2==l%2),_=>false}}
fn shells(study:&Study,phase:char)->Vec<Shell>{let mut m=BTreeMap::new();for h in 0..=study.hmax{for k in 0..=h{for l in 0..=k{if h+k+l==0||!allowed(phase,h,k,l){continue;}let n=h*h+k*k+l*l;m.entry(n).or_insert((h,k,l));}}}m.into_iter().map(|(n,(h,k,l))|Shell{n,h,k,l}).collect()}
fn greedy(study:&Study,si:usize,sh:&[Shell],a:i64,z:i64)->Option<ScanPlan>{let scan=&study.scans[si];let mut used=BTreeSet::new();let mut assign=Vec::new();let mut residual=0;let mut weight=0;let mut last=0;let mut imp=0;for p in &scan.peaks{let mut best=None;for s in sh{if s.n<=last||used.contains(&s.n){continue;}let r=(p.q-(a*s.n as i64+z)).abs();if r<=p.tol&&best.map_or(true,|(br,bn):(i64,i32)|r<br||(r==br&&s.n<bn)){best=Some((r,s.n));}}if let Some((r,n))=best{assign.push(n);used.insert(n);last=n;residual+=r;weight+=p.weight;}else{assign.push(0);imp+=1;}}if imp>study.max_impurities{return None;}let mut missing=Vec::new();if let(Some(lo),Some(hi))=(used.iter().next(),used.iter().next_back()){for s in sh{let q=a*s.n as i64+z;if s.n>*lo&&s.n<*hi&&q>=study.scan_lo&&q<=study.scan_hi&&!used.contains(&s.n){missing.push(s.n);}}}if missing.len()>study.max_missing{return None;}Some(ScanPlan{assign,missing,residual,weight})}
pub fn solve(study:&Study)->Option<Plan>{let mut best=None;for &phase in &study.phases{let sh=shells(study,phase);for a0 in study.scale_min..=study.scale_max{for a1 in study.scale_min..=study.scale_max{if(a1-a0).abs()>study.drift{continue;}for z0 in study.shift_min..=study.shift_max{for z1 in study.shift_min..=study.shift_max{let p0=match greedy(study,0,&sh,a0,z0){Some(x)=>x,None=>continue};let p1=match greedy(study,1,&sh,a1,z1){Some(x)=>x,None=>continue};let s0:BTreeSet<_>=p0.assign.iter().copied().filter(|x|*x>0).collect();let s1:BTreeSet<_>=p1.assign.iter().copied().filter(|x|*x>0).collect();let consensus=s0.intersection(&s1).count();if consensus<study.min_consensus{continue;}let obj=Objective{indexed_weight:p0.weight+p1.weight,consensus,residual:p0.residual+p1.residual,missing:p0.missing.len()+p1.missing.len(),orphans:s0.symmetric_difference(&s1).count(),motion:(a1-a0).abs()+(z1-z0).abs()};let cand=Plan{phase,a:[a0,a1],z:[z0,z1],scans:[p0,p1],objective:obj,optimal_count:1,shells:sh.clone()};if best.as_ref().map_or(true,|b:&Plan|cand.objective.indexed_weight>b.objective.indexed_weight||(cand.objective.indexed_weight==b.objective.indexed_weight&&cand.objective.residual<b.objective.residual)){best=Some(cand);}}}}}}best}
